"use strict";(globalThis.webpackChunktemp_docs=globalThis.webpackChunktemp_docs||[]).push([[8130],{7735(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"welcome","metadata":{"permalink":"/blog/welcome","editUrl":"https://github.com/socialdocs/socialdocs.org/tree/gh-pages/blog/2024-01-01-welcome.md","source":"@site/blog/2024-01-01-welcome.md","title":"Welcome to SocialDocs","description":"We\'re excited to launch SocialDocs \u2014 the comprehensive developer resource for ActivityPub, Mastodon, and the Fediverse.","date":"2024-01-01T00:00:00.000Z","tags":[{"inline":true,"label":"announcement","permalink":"/blog/tags/announcement"},{"inline":true,"label":"fediverse","permalink":"/blog/tags/fediverse"},{"inline":true,"label":"activitypub","permalink":"/blog/tags/activitypub"}],"readingTime":0.98,"hasTruncateMarker":true,"authors":[{"name":"SocialDocs Team","title":"Documentation Team","url":"https://socialdocs.org","imageURL":"https://socialdocs.org/img/logo.svg","key":"socialdocs","page":null}],"frontMatter":{"slug":"welcome","title":"Welcome to SocialDocs","authors":["socialdocs"],"tags":["announcement","fediverse","activitypub"]},"unlisted":false},"content":"We\'re excited to launch **SocialDocs** \u2014 the comprehensive developer resource for ActivityPub, Mastodon, and the Fediverse.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Our Mission\\n\\nBuilding for the Fediverse should be accessible to every developer. Whether you\'re creating a new social platform, adding federation to an existing app, or just curious about how it all works, SocialDocs aims to be your go-to resource.\\n\\n## What You\'ll Find Here\\n\\n- **Getting Started Guides**: From \\"What is the Fediverse?\\" to building your first ActivityPub server\\n- **Protocol Specifications**: Deep dives into ActivityPub, ActivityStreams, WebFinger, and HTTP Signatures\\n- **Implementation Guides**: Step-by-step tutorials for common tasks\\n- **API Reference**: Complete documentation for object types, activities, and endpoints\\n- **Ecosystem Directory**: Overview of server software, libraries, and tools\\n- **Developer Tools**: Validators, inspectors, and testing resources\\n\\n## Contributing\\n\\nSocialDocs is open source and community-driven. We welcome contributions from everyone:\\n\\n- **Found an error?** [Open an issue](https://github.com/socialdocs/socialdocs.org/issues)\\n- **Want to add content?** Check our [contribution guide](/docs/community/contributing)\\n- **Have feedback?** Reach out on the Fediverse\\n\\n## Join the Community\\n\\n- [SocialHub Forum](https://socialhub.activitypub.rocks/) - ActivityPub discussions\\n- [Fediverse Developers](https://fedidevs.org/) - Developer community\\n- [W3C Social CG](https://www.w3.org/community/socialcg/) - Standards development\\n\\nLet\'s build the open social web together!"}]}}')}}]);